function posicionarGf(){const novo=document.querySelector('#view .gfpainel');document.querySelectorAll('body > .gfpainel').forEach(x=>{if(novo||!st.gfAberto)x.remove()});
 if(novo){document.body.appendChild(novo);const i=novo.querySelector('[data-df-gfbusca]');if(i){i.focus();const n=i.value.length;i.setSelectionRange(n,n)}}
 const p=document.querySelector('body > .gfpainel'),b=st.gfAberto&&document.querySelector(`[data-df-gf="${st.gfAberto}"]`);if(!p||!b)return;const r=b.getBoundingClientRect();
 if(r.bottom<0||r.top>innerHeight){st.gfAberto=null;render();return}
 p.style.left=Math.max(8,Math.min(r.right-p.offsetWidth,innerWidth-p.offsetWidth-8))+'px';p.style.top=Math.max(8,Math.min(r.bottom+4,innerHeight-p.offsetHeight-8))+'px';p.style.visibility='visible'}
