 const passos=[[true,'Notas de venda lidas do Bling a cada 2 minutos (DIFAL e FCP de cada nota).'],[!!(e.endereco&&e.ibge&&e.cep),'Dados do emitente para a guia (abaixo).'],[!!d.certificado,'Certificado A1 instalado no servidor: a instalação é feita pela equipe Jarvis — abra um chamado na Central de ajuda.'],[false,'Acesso ao webservice liberado no Portal GNRE (www.gnre.pe.gov.br › Área do contribuinte › Solicitar acesso ao webservice, com o mesmo certificado).'],[d.ambiente==='producao','Testado em homologação e trocado para produção (a troca é feita pela equipe Jarvis: peça pela Central de ajuda).']];
