function view(){if(st.dia&&(fimP()<`${month}-01`||st.dia>`${month}-31`)){st.dia='';st.ate=''} // trocou o mês no topo: período de outro mês sai
 if(st.notas&&st.mesCarregado!==cargaChave()){st.notas=null;st.guias=null;st.sel.clear()}
 if(!st.notas){carregar();return '<div class="empty">Carregando…</div>'}
 const A=[['notas','Notas'],['guias',`Guias (${st.guias.filter(g=>['rascunho','enviada','emitida','rejeitada'].includes(g.status)).length})`],['mensal','Apuração mensal'],['config','Configuração']];
 return `<div class="crmbar"><div class="segtabs">${A.map(([k,t])=>`<button class="${st.aba===k?'active':''}" data-df-aba="${k}">${t}</button>`).join('')}</div><div style="flex:1"></div>${st.aba==='notas'?diaBar():''}</div>${kpis()}${({notas:notasView,guias:guiasView,mensal:mensalView,config:configView}[st.aba]||notasView)()}`}

function diaBar(){const h=hoje(),dd=n=>new Date(Date.now()-n*864e5).toLocaleDateString('sv-SE'),ont=dd(1),sete=dd(6),um=!st.ate||st.ate===st.dia,eh=(a,b)=>st.dia===a&&fimP()===b;
 return `<div class="row" style="gap:6px;flex-wrap:wrap;align-items:center"><span class="caption">Emitidas de</span><input id="dfDia" type="date" data-df="de" aria-label="Emitidas a partir de" value="${st.dia}" max="${h}"><span class="caption">até</span><input type="date" data-df="ate" aria-label="Emitidas até" value="${st.dia?fimP():''}" min="${st.dia}" max="${h}"><button class="small ${eh(h,h)?'primary':'quiet'}" data-df-dia="${h}">Hoje</button><button class="small ${eh(ont,ont)?'primary':'quiet'}" data-df-dia="${ont}">Ontem</button><button class="small ${eh(sete,h)?'primary':'quiet'}" data-df-periodo="${sete}|${h}">7 dias</button><button class="small ${!st.dia?'primary':'quiet'}" data-df-dia="">Mês todo</button>${st.dia&&um&&pode()?`<button class="small" data-df-lerdia title="Busca no Bling agora as notas deste dia, sem esperar a leitura automática">${icon('refresh')} Ler notas deste dia agora</button>`:''}</div>`}
// Período: datas trocadas se vierem invertidas; até 93 dias (a tela carrega até 5.000 notas).
function escolherPeriodo(de,ate){const ok=v=>/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(v||'');if(!ok(de))return escolherDia(ate);if(!ok(ate)||ate===de)return escolherDia(de);if(ate<de)[de,ate]=[ate,de];
 if((new Date(ate)-new Date(de))/864e5>92){toast('Escolha um período de até 3 meses.');render();return}
 st.dia=de;st.ate=ate;st.sel.clear();st.sit='pendente';if(ate<`${month}-01`||de>`${month}-31`){month=ate.slice(0,7);st.notas=null}render()}
const recarregar=()=>{st.notas=null;st.guias=null;carregar()};
function escolherDia(v){st.ate='';st.dia=/^\d{4}-\d{2}-\d{2}$/.test(v||'')?v:'';st.sel.clear();st.sit='pendente';if(st.dia&&!st.dia.startsWith(month)){month=st.dia.slice(0,7);st.notas=null}render()}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-df-fcp],[data-df-temporarias],[data-df-uflimpar],[data-df-prontas],[data-df-testes],[data-df-dia],[data-df-periodo],[data-df-lerdia],[data-df-aba],[data-df-uf],[data-df-preparar],[data-df-agrupar],[data-df-estornar],[data-df-ignorar],[data-df-enviar],[data-df-xml],[data-df-consultar],[data-df-copiar],[data-df-pdf],[data-df-cancelar],[data-df-mensal],[data-df-cfg],[data-df-ler],[data-df-sispag]');if(!b)return;const d=b.dataset;
 if(d.dfDia!=null){escolherDia(d.dfDia);return}
 if(d.dfPeriodo){const [a,b2]=d.dfPeriodo.split('|');escolherPeriodo(a,b2);return}
 if(d.dfAba){st.aba=d.dfAba;render();return}
 if(d.dfTemporarias!==undefined){st.gsel=new Set(st.guias.filter(g=>st.gVis.includes(g.id)&&rejeicao(g)?.tipo==='temp').map(g=>g.id));render();return}
 if(d.dfUflimpar!==undefined){st.ufs.clear();st.ufAberto=false;st.sel.clear();render();return}
 if(d.dfUf){st.ufs=new Set([d.dfUf]);st.sit='todas';render();return}
 if(d.dfSispag!=null)return navigate('sispag');
 if(d.dfCopiar){try{await navigator.clipboard.writeText(d.dfCopiar);toast('Linha digitável copiada.')}catch{toast(d.dfCopiar)}return}
 b.disabled=true;
 try{
  if(d.dfTestes!=null){st.verTestes=!st.verTestes;render();return}
  if(d.dfProntas!=null){st.gsel=new Set(st.guias.filter(g=>st.gVis.includes(g.id)&&['rascunho','rejeitada'].includes(g.status)&&(st.verTestes||g.ambiente!=='homologacao'||g.status!=='emitida')).map(g=>g.id));render();return}
  if(d.dfAgrupar!=null){const ch=[...st.sel];const r=await gnre('preparar',{chaves:ch,agrupar:true});st.sel.clear();const g=r.guias[0];toast(`Guia única de ${g.uf} preparada com ${g.notas??ch.length} nota(s): ${money(g.total)}. Envie na aba Guias.`);st.aba='guias';recarregar();return}
  if(d.dfPreparar!=null){const ch=[...st.sel];const r=await gnre('preparar',{chaves:ch});st.sel.clear();toast(`${r.guias.length} guia(s) preparada(s)${r.guias.length<ch.length?` · ${ch.length-r.guias.length} nota(s) cancelada(s) no Bling ficaram de fora`:''}.`);st.aba='guias';recarregar();return}
  if(d.dfIgnorar!=null){if(b.dataset.conf!=='1'){b.disabled=false;b.dataset.conf='1';b.textContent=`Confirmar: ${st.sel.size} já paga(s) fora do Jarvis`;b.classList.add('danger');return}
   const {error}=await Cloud.client.from('difal_notas').update({situacao:'ignorada',updated_at:new Date().toISOString()}).eq('workspace_id',Cloud.ws).in('chave',[...st.sel]).eq('situacao','pendente');if(error)throw error;audit('DIFAL: notas marcadas como pagas fora do Jarvis',`${st.sel.size} nota(s)`);st.sel.clear();recarregar();return}
  if(d.dfEnviar!=null){if(b.dataset.conf!=='1'){b.disabled=false;b.dataset.conf='1';b.textContent=`Confirmar envio (${st.diag?.ambiente==='producao'?'PRODUÇÃO':'homologação'})`;b.classList.add('danger');return}
   if(st.pag==='fixa'&&!(st.pagData>=hoje()))throw Error('Escolha a data de pagamento (a partir de hoje).');const r=await gnre('enviar',{ids:[...st.gsel],pagamento:opcPag()});st.gsel.clear();const rc=r.recibos||[r.recibo];toast(`${r.guias} guia(s) enviada(s) em ${rc.length} lote(s)${r.falha?` · ${r.pendentes} ficaram para reenviar (${r.falha})`:''}. O Jarvis acompanha o portal e avisa quando saírem.`);acompanhar(rc,(r.lotes||[]).flatMap(l=>l.ids||[]),opcPag());recarregar();return}
  if(d.dfXml!=null){if(st.pag==='fixa'&&!(st.pagData>=hoje()))throw Error('Escolha a data de pagamento (a partir de hoje).');const r=await gnre('xml',{ids:[...st.gsel],pagamento:opcPag()});download(`gnre-lote-${hoje()}.xml`,r.xml,'application/xml');toast(`XML com ${r.guias} guia(s). Envie em www.gnre.pe.gov.br › Lote de GNRE.`);b.disabled=false;return}
  if(d.dfConsultar!=null){const r=await gnre('consultar');const em=r.resultado.filter(x=>x.status==='emitida'&&!x.teste).length,tst=r.resultado.filter(x=>x.status==='emitida'&&x.teste).length,rj=r.resultado.filter(x=>x.status==='rejeitada').length;toast(em||tst||rj?[em?`${em} emitida(s) e lançada(s) no contas a pagar`:'',tst?`${tst} guia(s) de TESTE emitida(s) (não pagar; as notas voltaram para a fila)`:'',rj?`${rj} rejeitada(s): veja o motivo na lista`:''].filter(Boolean).join(' · ')+'.':'O portal ainda está processando.');if(em)await window.Cloud?.reload?.();recarregar();return}
  if(d.dfPdf!=null){const {data,error}=await Cloud.client.from('gnre_guias').select('pdf_base64').eq('workspace_id',Cloud.ws).eq('recibo',d.dfPdf).not('pdf_base64','is',null).limit(1);if(error)throw error;let p=data?.[0]?.pdf_base64;
   // Sem PDF gravado: pede de novo ao portal (o servidor guarda para a próxima vez).
   if(!p){b.innerHTML='Buscando no portal…';try{p=(await gnre('pdf',{recibo:d.dfPdf}))?.pdf}catch(x){p=null}b.innerHTML=`${icon('download')} PDF`}
   if(!p){b.disabled=false;const g=st.guias.find(x=>x.recibo===d.dfPdf&&x.linha_digitavel);if(g)try{await navigator.clipboard.writeText(g.linha_digitavel)}catch(x){}return toast(`O portal GNRE não devolveu o PDF deste lote. A guia vale pela linha digitável${g?' (copiada; também está no contas a pagar)':''}; para imprimir, consulte o lote ${d.dfPdf} em www.gnre.pe.gov.br.`)}
   const bin=Uint8Array.from(atob(p),c=>c.charCodeAt(0));download(`gnre-${d.dfPdf}.pdf`,bin,'application/pdf');b.disabled=false;return}
  if(d.dfEstornar){if(b.dataset.conf!=='1'){b.disabled=false;b.dataset.conf='1';b.textContent=d.emitida?'Confirmar estorno: sai do contas a pagar (não pague a guia antiga)':'Confirmar estorno';b.classList.add('danger');return}
   const r=await gnre('estornar',{id:d.dfEstornar});st.gsel.delete(d.dfEstornar);toast(`Guia estornada: ${r.notas} nota(s) de volta para Sem guia${r.titulo_cancelado?' e o título saiu do contas a pagar. Não pague a guia antiga':''}.`);if(r.titulo_cancelado)await window.Cloud?.reload?.();recarregar();return}
  if(d.dfFcp){const ids=d.dfFcp.split(',').filter(Boolean),r=await gnre('complementar_fcp',{ids});toast(r.guias.length?`${r.guias.length} guia(s) do FCP preparada(s) em rascunho (${money(r.guias.reduce((x,g)=>x+Number(g.total),0))}). Marque e envie ao Portal GNRE.`:'Nada a complementar: essas guias já cobram o FCP ou já têm a guia do FCP.');recarregar();return}
  if(d.dfCancelar){await gnre('cancelar_rascunho',{id:d.dfCancelar});st.gsel.delete(d.dfCancelar);recarregar();return}
  if(d.dfMensal){const r=await gnre('preparar',{mensal:{uf:d.dfMensal,mes:month}});toast(`Guia mensal de ${d.dfMensal} preparada: ${money(r.guias[0]?.total||0)}.`);st.aba='guias';recarregar();return}
  if(d.dfCfg){const r=await gnre('config_uf',{uf:d.dfCfg});modal(`Exigências de ${d.dfCfg} (receita 100102)`,`<pre style="white-space:pre-wrap;font-size:12px">${esc(JSON.stringify(r,null,1))}</pre><div class="modalfoot"><button class="primary" data-action="close">Fechar</button></div>`);b.disabled=false;return}
  if(d.dfLerdia!=null){b.innerHTML='Lendo no Bling…';const r=await integ('difal_sync',{dia:st.dia});toast(`${new Date(st.dia+'T12:00').toLocaleDateString('pt-BR')}: ${r.lidas} nota(s) nova(s) lida(s), ${r.com_difal} com DIFAL${r.completo?'':'. Ainda faltam notas deste dia: clique de novo'}.`);recarregar();return}
  if(d.dfLer!=null){const desde=$('#dfDesde').value;const r=await integ('difal_sync',{desde});toast(`${r.lidas} nota(s) lida(s) · ${r.com_difal} com DIFAL. O restante segue pelo cron.`);recarregar();return}
 }catch(x){b.disabled=false;toast(x.message)}});
document.addEventListener('change',e=>{const x=e.target;
 if(x.matches('[data-df="de"]')){escolherPeriodo(x.value,st.ate||x.value);return}
 if(x.matches('[data-df="ate"]')){escolherPeriodo(st.dia||x.value,x.value);return}
 if(x.matches('[data-df-pagmodo]')){st.pag=x.value==='fixa'?'fixa':'auto';if(st.pag==='fixa'&&!st.pagData)st.pagData=hoje();try{localStorage.setItem('eb_gnre_pag',st.pag)}catch{}render();return}
 if(x.matches('[data-df-pagdata]')){st.pagData=x.value;render();return}
 if(x.matches('[data-df-auto]')){salvarFiscal({gnre_auto:x.checked});audit('GNRE automática',x.checked?'ligada':'desligada');toast(x.checked?'GNRE automática ligada: os rascunhos aparecem todo dia às 7 h.':'GNRE automática desligada.');return}
 if(x.matches('[data-df-ufchk]')){const u=x.dataset.dfUfchk;if(x.checked)st.ufs.add(u);else st.ufs.delete(u);st.ufAberto=true;st.sel.clear();render();return}
 if(x.matches('[data-df-uftodas]')){st.ufs.clear();st.ufAberto=true;st.sel.clear();render();return}
 if(x.matches('[data-df="sit"]')){st.sit=x.value;st.sel.clear();render();return}
 if(x.matches('[data-df-sel]')){x.checked?st.sel.add(x.dataset.dfSel):st.sel.delete(x.dataset.dfSel);render();return}
 if(x.matches('[data-df-todas]')){const q=st.notas.filter(n=>noDia(n)&&(!st.ufs.size||st.ufs.has(n.uf))&&n.situacao==='pendente');if(x.checked)q.forEach(n=>st.sel.add(n.chave));else st.sel.clear();render();return}
 if(x.matches('[data-df-gsel]')){x.checked?st.gsel.add(x.dataset.dfGsel):st.gsel.delete(x.dataset.dfGsel);render();return}
 if(x.matches('[data-df-em]')){salvarFiscal({emitente:{...(fcfg().emitente||{}),[x.dataset.dfEm]:x.value.trim()}});toast('Salvo.');return}
 const u=x.dataset.dfIe||x.dataset.dfDia||x.dataset.dfFcp;if(u){const D={...duf()},v={...(D[u]||{})};if(x.dataset.dfIe)v.ie=x.value.replace(/[^\dA-Za-z]/g,'');else if(x.dataset.dfDia)v.dia=Number(x.value)||null;else v.fcp_separado=x.checked;
  if(!v.ie&&!v.fcp_separado&&!v.dia)delete D[u];else D[u]=v;salvarFiscal({difal_uf:D});if(x.dataset.dfIe&&window.Cloud?.client)Cloud.client.from('difal_notas').update({situacao:v.ie?'mensal':'pendente',updated_at:new Date().toISOString()}).eq('workspace_id',Cloud.ws).eq('uf',u).eq('situacao',v.ie?'pendente':'mensal').then(()=>recarregar());audit('DIFAL: configuração da UF',`${u} · ${v.ie?'IE '+v.ie:'sem IE'}`);toast(`${u} salvo. ${v.ie?'Notas novas dessa UF entram na apuração mensal.':''}`)}});

// ─── Inscrições estaduais (substituto tributário) — também aparece em Regras fiscais ───
const stIe={novo:false};
const redesenhar=()=>setTimeout(render,0); // depois dos outros tratadores de clique da página
function inscricoesHtml(){const D=duf(),ufEmit=fcfg().uf||'',l=Object.entries(D).filter(([,v])=>v?.ie).sort((a,b)=>a[0].localeCompare(b[0])),usadas=new Set(l.map(([u])=>u)),livres=UFS.filter(u=>u!==ufEmit&&!usadas.has(u));
 return `<p class="caption">Nas UFs em que a empresa é inscrita como substituta tributária, o DIFAL das vendas do mês vira uma guia só, no dia de vencimento da UF. Nas demais, uma GNRE por nota. Em "Vale desde", a data em que a inscrição passou a valer: as notas anteriores seguem com GNRE por nota. Marque "FCP separado" se a UF exigir o FCP na receita 100129.</p>
 <div class="tablewrap"><table><thead><tr><th>Estado</th><th>Inscrição estadual</th><th>Vale desde</th><th class="num">Dia do vencimento</th><th>FCP separado</th><th></th></tr></thead><tbody>
 ${l.map(([u,v])=>`<tr><td><strong>${u}</strong></td><td><input class="ufin" data-ie-campo="ie" data-ie-uf="${u}" value="${esc(v.ie)}" style="width:170px" aria-label="Inscrição estadual ${u}"></td><td><input class="ufin" type="date" data-ie-campo="desde" data-ie-uf="${u}" value="${esc(v.desde||'')}" title="Notas emitidas antes desta data seguem com GNRE por nota. Em branco: todas as notas sem guia entram na apuração." aria-label="Inscrição de ${u} vale desde"></td><td class="num"><input class="ufin" type="number" min="1" max="31" data-ie-campo="dia" data-ie-uf="${u}" value="${esc(v.dia||'')}" placeholder="10" style="width:70px" aria-label="Dia do vencimento ${u}"></td><td><input type="checkbox" class="check" data-ie-campo="fcp" data-ie-uf="${u}" ${v.fcp_separado?'checked':''} aria-label="FCP separado ${u}"></td><td><button class="small quiet" data-ie-remover="${u}" title="Remover inscrição de ${u}">${icon('x')}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhuma inscrição cadastrada: o DIFAL é pago por nota em todas as UFs.</td></tr>'}
 ${stIe.novo?`<tr><td><select id="ieNovoUf">${livres.map(u=>`<option>${u}</option>`).join('')}</select></td><td><input id="ieNovoNum" class="ufin" placeholder="Número da inscrição" style="width:170px"></td><td><input id="ieNovoDesde" class="ufin" type="date" value="${new Date(Date.now()-3*36e5).toISOString().slice(0,10)}" aria-label="Vale desde"></td><td class="num"><input id="ieNovoDia" class="ufin" type="number" min="1" max="31" placeholder="10" style="width:70px"></td><td><input id="ieNovoFcp" type="checkbox" class="check"></td><td><button class="small primary" data-ie-salvar>Salvar</button> <button class="small quiet" data-ie-cancelar>Cancelar</button></td></tr>`:''}
 </tbody></table></div>${stIe.novo||!pode()?'':`<button class="small" data-ie-add style="margin-top:8px">${icon('plus')} Adicionar outra inscrição</button>`}`}
function gravarIe(u,v,antes){const D={...duf()};if(v)D[u]=v;else delete D[u];salvarFiscal({difal_uf:D});
 /* Reclassifica só notas sem guia: com inscrição, as de "vale desde" em diante vão para a apuração mensal e as anteriores voltam para GNRE por nota. */
 const tinha=!!antes?.ie,tem=!!v?.ie;if((tinha!==tem||(tem&&(antes?.desde||'')!==(v.desde||'')))&&window.Cloud?.client)try{const agora=new Date().toISOString(),up=(para,de)=>Cloud.client.from('difal_notas').update({situacao:para,updated_at:agora}).eq('workspace_id',Cloud.ws).eq('uf',u).eq('situacao',de).is('guia_id',null),ops=[];
  if(tem){let a=up('mensal','pendente');if(v.desde)a=a.gte('emissao',v.desde);ops.push(a);if(v.desde)ops.push(up('pendente','mensal').lt('emissao',v.desde))}else ops.push(up('pendente','mensal'));
  Promise.all(ops).then(()=>{if(page==='difal')recarregar()},()=>{})}catch(e){console.warn('DIFAL: notas não reclassificadas',e)}
 audit('Inscrição estadual (substituto tributário)',`${u} · ${v?.ie?'IE '+v.ie+(v.desde?' desde '+v.desde.split('-').reverse().join('/'):''):'removida'}`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-ie-add],[data-ie-cancelar],[data-ie-salvar],[data-ie-remover]');if(!b)return;const d=b.dataset;
 if(d.ieAdd!=null){stIe.novo=true;redesenhar();setTimeout(()=>$('#ieNovoNum')?.focus(),30);return}
 if(d.ieCancelar!=null){stIe.novo=false;redesenhar();return}
 if(d.ieSalvar!=null){const u=$('#ieNovoUf')?.value,ie=String($('#ieNovoNum')?.value||'').replace(/[^\dA-Za-z]/g,'');if(!u||!ie)return toast('Escolha o estado e informe a inscrição.');
  const desde=$('#ieNovoDesde')?.value||null;gravarIe(u,{ie,desde,dia:Number($('#ieNovoDia')?.value)||null,fcp_separado:!!$('#ieNovoFcp')?.checked},duf()[u]);stIe.novo=false;redesenhar();toast(`Inscrição de ${u} salva. Notas de ${u}${desde?' a partir de '+desde.split('-').reverse().join('/'):''} entram na apuração mensal.`);return}
 if(d.ieRemover){if(b.dataset.conf!=='1'){b.dataset.conf='1';b.textContent='Confirmar';b.classList.add('danger');return}const u=d.ieRemover,antes=duf()[u];gravarIe(u,null,antes);redesenhar();toast(`Inscrição de ${u} removida: o DIFAL de ${u} volta a ser por nota.`)}});
document.addEventListener('change',e=>{const x=e.target.closest('[data-ie-campo]');if(!x)return;const u=x.dataset.ieUf,antes=duf()[u]||{},v={...antes};
 if(x.dataset.ieCampo==='ie'){v.ie=x.value.replace(/[^\dA-Za-z]/g,'');if(!v.ie){x.value=antes.ie||'';return toast('Para tirar a inscrição, use o botão de remover.')}}
 else if(x.dataset.ieCampo==='dia')v.dia=Number(x.value)||null;else if(x.dataset.ieCampo==='desde')v.desde=x.value||null;else v.fcp_separado=x.checked;
 gravarIe(u,v,antes);toast(`${u} salvo.`)});
addPage('difal','guia','DIFAL e GNRE',view,'DIFAL e FCP de cada nota lidos do Bling, guias GNRE por nota ou mensais pelo webservice do portal, e pagamento pelo arquivo do banco.','',()=>{});
window.Difal={carregar,inscricoesHtml,dataPagamento,diaUtilSeguinte,valorDoCodigo,faltaNaGuia,avisos:()=>{const p=(st.notas||[]).filter(x=>x.situacao==='pendente');return p.length?[['warn','guia',`${p.length} nota(s) com DIFAL sem guia`,money(p.reduce((s,x)=>s+Number(x.v_difal)+Number(x.v_fcp),0)),'difal']]:[]}};
